import * as React from "react"
import { LEVELS, TIERS, tierForLevel } from "../../data/plans"
import { formatMoney } from "../../config/pricing"
import { Check } from "../Icons"
import HelpTip from "./HelpTip"
import * as s from "./Builder.module.css"

/**
 * The benefits list, as checkboxes — MTC-FCS-017.
 * ============================================================================
 * The same green-ticked list that has always described what you get, except
 * the ticks are now the control: checking one is how a tier is chosen, and the
 * tabs above are the same state seen from the other side.
 *
 * ── ONE ANCHOR PER LEVEL, AND IT CARRIES THE PRICE ─────────────────────────
 * The first item in each level is its switch. Checking it turns the whole
 * level on; unchecking it turns the whole level off, because a level is a
 * thing you are on or not, not a menu. The price sits on that row rather than
 * in a separate panel, so what a tick costs is never a scroll away.
 *
 * ── CHECKING ANY ITEM BUYS ITS LEVEL ───────────────────────────────────────
 * Ticking "a gallery of your own work" ticks hosting too. Letting somebody
 * assemble a basket of individual features would be a different product, and
 * the honest version of this one is that these arrive together.
 *
 * ── UNTICKING A FEATURE TURNS IT OFF, NOT THE PRICE OFF ────────────────────
 * The items marked with a `feature` genuinely change the website, so a
 * contractor who does not want the gallery can say so. The price does not move
 * — they are still on the level — and the row says as much rather than
 * implying a discount that will not appear on the invoice.
 *
 * ── LEVELS STACK ───────────────────────────────────────────────────────────
 * Turning on Lead Generation turns on Premium underneath it, because it is
 * priced as an addition to it. Turning Premium off takes Lead Generation with
 * it, for the same reason.
 */

/* The (?) sits OUTSIDE the checkbox button — MTC-FCS-026. Nesting a button
   inside a button is invalid markup and behaves differently in every browser;
   asking a question about a benefit must not buy it. */
const Row = ({ item, checked, price, onToggle, disabled }) => (
  <li className={`${s.benefit} ${checked ? s.benefitOn : ""}`}>
    <button
      type="button"
      role="checkbox"
      aria-checked={checked}
      disabled={disabled}
      className={s.benefitHit}
      onClick={onToggle}
    >
      <span className={s.benefitMark} aria-hidden="true">
        {checked ? <Check /> : null}
      </span>
      <span className={s.benefitLabel}>{item.label}</span>
      {price ? <span className={s.benefitPrice}>{price}</span> : null}
    </button>
    {item.help ? <HelpTip text={item.help} label={item.label} /> : null}
  </li>
)

const PlanBenefits = ({ tier, checked, onChange }) => {
  const on = id => Boolean(checked[id])

  /** Which levels the current tier includes. */
  const levelOn = level => TIERS[tier] && TIERS[tier].levels.includes(level.id)

  const setTier = (nextTier, nextChecked) => onChange(nextTier, nextChecked)

  /** Everything in a level, ticked or cleared together. */
  const fillLevel = (level, value, base) => {
    const next = { ...base }
    for (const item of level.items) next[item.id] = value
    return next
  }

  const toggleLevel = (level, wantOn) => {
    const index = LEVELS.indexOf(level)
    let next = { ...checked }
    let nextTier

    if (wantOn) {
      // Everything at or below this level comes on with it: this level is
      // priced as an addition to those, so it cannot be had without them.
      for (const lower of LEVELS.slice(0, index + 1)) next = fillLevel(lower, true, next)
      nextTier = level.tier
    } else {
      // …and everything above it goes off, for the same reason.
      for (const higher of LEVELS.slice(index)) next = fillLevel(higher, false, next)
      nextTier = index === 0 ? "free" : tierForLevel(LEVELS[index - 1].id)
    }
    setTier(nextTier, next)
  }

  const toggleItem = (level, item) => {
    if (item.anchor) {
      toggleLevel(level, !on(item.id))
      return
    }
    if (!on(item.id)) {
      // Ticking a benefit buys the level it belongs to.
      const index = LEVELS.indexOf(level)
      let next = { ...checked }
      for (const lower of LEVELS.slice(0, index + 1)) next = fillLevel(lower, true, next)
      setTier(level.tier, { ...next, [item.id]: true })
      return
    }
    // Clearing one benefit leaves the level (and the price) exactly where it
    // was — see the note at the top.
    setTier(tier, { ...checked, [item.id]: false })
  }

  return (
    <div className={s.benefitStack}>
      {LEVELS.map((level, i) => {
        const anchor = level.items.find(item => item.anchor)
        const included = levelOn(level)
        return (
          <div
            key={level.id}
            className={`${s.benefitLevel} ${included ? s.benefitLevelOn : ""}`}
          >
            <ul className={s.benefitList}>
              {level.items.map(item => (
                <Row
                  key={item.id}
                  item={item}
                  checked={on(item.id)}
                  price={
                    item.anchor
                      ? `${i === 0 ? "" : "+"}${formatMoney(level.amount)}/mo`
                      : null
                  }
                  onToggle={() => toggleItem(level, item)}
                />
              ))}
            </ul>
            {included && anchor ? (
              <p className={s.benefitNote}>
                Untick anything you do not want on your site. It stays{" "}
                {formatMoney(TIERS[level.tier].amount)} a month either way.
              </p>
            ) : null}
          </div>
        )
      })}
    </div>
  )
}

export default PlanBenefits
