import * as React from "react"
import { servicesForTrade, tradeBySlug } from "../../data/trades"
import { ArrowRight, Check } from "../Icons"
import * as s from "./Builder.module.css"

const MAX = 3

/**
 * Question two: your top three services.
 *
 * Three, because three is what the generated home page renders, and asking for
 * a number the design cannot show would either truncate their answer silently
 * or produce a lopsided page. The screen says plainly that more can be added
 * later, which is true and is the thing people worry about here.
 *
 * ORDER IS THE PICK ORDER, and the rank badge says so. The first service
 * chosen is the first card on the site, so a contractor who leads with
 * emergency call-outs gets a page that leads with emergency call-outs.
 *
 * The free-text box exists because a nine-item list will never cover a trade.
 * Anything typed here is treated exactly like a suggested one.
 */
const StepServices = ({ draft, update, next, back }) => {
  const trade = tradeBySlug(draft.tradeSlug)
  const [custom, setCustom] = React.useState("")

  // Anything already chosen that the trade does not suggest — typed by hand, or
  // sent by a trade landing page whose wording differs from ours ("Cabinet
  // Painting" vs "Cabinet Refinishing") — is shown as a chip of its own.
  // Without this it would appear only in the list below, which reads as though
  // the selection did not take.
  const suggested = servicesForTrade(draft.tradeSlug)
  const extras = draft.services.filter(
    name => !suggested.some(s => s.toLowerCase() === name.toLowerCase())
  )
  const suggestions = [...suggested, ...extras]

  const picked = draft.services
  const full = picked.length >= MAX

  const toggle = name => {
    const already = picked.indexOf(name)
    if (already > -1) {
      update({ services: picked.filter(x => x !== name) })
      return
    }
    if (full) return
    update({ services: [...picked, name] })
  }

  const addCustom = e => {
    e.preventDefault()
    const name = custom.trim()
    if (!name || full) return
    // Case-insensitive, so "roof repair" cannot be added beside "Roof Repair".
    if (picked.some(x => x.toLowerCase() === name.toLowerCase())) {
      setCustom("")
      return
    }
    update({ services: [...picked, name] })
    setCustom("")
  }

  return (
    <div>
      <h1 className={s.question}>
        Which {trade ? trade.name.toLowerCase() : ""} services do you want to lead with?
      </h1>
      <p className={s.hint}>
        Pick up to three — these become the three cards on your home page, in the order you choose
        them. You can add more services once your site is live.
      </p>

      <div className={s.chips}>
        {suggestions.map(name => {
          const rank = picked.indexOf(name)
          const on = rank > -1
          return (
            <button
              key={name}
              type="button"
              className={`${s.chip} ${on ? s.chipOn : ""}`}
              disabled={!on && full}
              onClick={() => toggle(name)}
            >
              {on ? <span className={s.chipRank}>{rank + 1}</span> : null}
              {name}
            </button>
          )
        })}
      </div>

      <form onSubmit={addCustom}>
        <label className={s.fieldLabel} htmlFor="custom-service">
          Something else you offer?
        </label>
        <div className={s.customRow}>
          <input
            id="custom-service"
            className={s.input}
            value={custom}
            onChange={e => setCustom(e.target.value)}
            placeholder="e.g. Skylight installation"
            disabled={full}
            maxLength={48}
          />
          <button type="submit" className="btn btn--sm" disabled={full || !custom.trim()}>
            Add
          </button>
        </div>
        <p className={s.fieldNote}>
          {full
            ? "That is three. Remove one to swap it for something else."
            : `${MAX - picked.length} more to choose.`}
        </p>
      </form>

      {picked.length > 0 && (
        <div className={s.picked}>
          <p className={s.pickedTitle}>Your services, in order</p>
          <div className={s.pickedList}>
            {picked.map((name, i) => (
              <div key={name} className={s.pickedItem}>
                <Check style={{ width: 18, height: 18, flex: "none" }} />
                <span>
                  {i + 1}. {name}
                </span>
                <button type="button" onClick={() => toggle(name)}>
                  Remove
                </button>
              </div>
            ))}
          </div>
        </div>
      )}

      <div className={s.actions}>
        <button type="button" className={s.back} onClick={back}>
          Back
        </button>
        <button
          type="button"
          className={`btn btn--lg ${s.spacer}`}
          disabled={picked.length === 0}
          onClick={next}
        >
          Continue
          <ArrowRight className="btn__arrow" />
        </button>
      </div>
    </div>
  )
}

export default StepServices
