import * as React from "react"
import * as s from "./Builder.module.css"

/**
 * The little (?) beside a benefit — MTC-FCS-026 (second use of the number).
 * ============================================================================
 * Some of the things on the benefits list do not explain themselves. "$200 in
 * custom design credits" is the obvious one: it is the most valuable line on
 * the page and the least self-evident, and it is where the conversation with a
 * higher-paying customer starts.
 *
 * ── HOVER IS NOT THE ONLY WAY IN ───────────────────────────────────────────
 * A tooltip that only appears on hover is invisible to every phone, every
 * keyboard and every screen reader. This one opens on hover, on focus and on
 * tap, closes on Escape, and the button carries the same text as its
 * accessible name — so the explanation is reachable even when the bubble is
 * not.
 *
 * ── IT IS A BUTTON, NOT A DIV WITH A TITLE ─────────────────────────────────
 * `title=""` is the tempting version and it is unusable: no keyboard access,
 * a second-long delay, and no control over where it appears or how long it
 * stays. A real button is four more lines and works for everybody.
 *
 * ── IT LIVES INSIDE A CHECKBOX ROW ─────────────────────────────────────────
 * The benefit row is itself a `role="checkbox"` button, so this one stops the
 * click from reaching it. Asking a question about a benefit must not buy it.
 */
const HelpTip = ({ text, label }) => {
  const [open, setOpen] = React.useState(false)
  const id = React.useId()

  const swallow = event => {
    event.preventDefault()
    event.stopPropagation()
  }

  return (
    <span
      className={s.tipWrap}
      onMouseEnter={() => setOpen(true)}
      onMouseLeave={() => setOpen(false)}
    >
      <button
        type="button"
        className={s.tipButton}
        aria-label={label ? `What is ${label}?` : "More about this"}
        aria-describedby={open ? id : undefined}
        aria-expanded={open}
        onFocus={() => setOpen(true)}
        onBlur={() => setOpen(false)}
        onKeyDown={e => {
          if (e.key === "Escape") setOpen(false)
        }}
        onClick={e => {
          // Tap-to-open, for the devices that have no hover at all.
          swallow(e)
          setOpen(v => !v)
        }}
      >
        ?
      </button>

      {open ? (
        <span id={id} role="tooltip" className={s.tipBubble} onClick={swallow}>
          {text}
        </span>
      ) : null}
    </span>
  )
}

export default HelpTip
