import * as React from "react"
import { US_STATES, stateByCode } from "../../data/us-states"
import {
  countyNames,
  fipsFor,
  loadCountiesFor,
  sortedCounties,
  featuresForState,
} from "../../lib/service-area-geo"
import ServiceAreaMap from "./ServiceAreaMap"
import { ArrowRight } from "../Icons"
import * as s from "./Builder.module.css"

/**
 * Question four: where do you work?
 *
 * ── AS MANY STATES AS THEY COVER — MTC-FCS-026 ─────────────────────────────
 * Ported from contractor.wiki. A roofer in Coeur d'Alene works in Idaho and
 * eastern Washington; a plumber in Delaware crosses three states before lunch.
 * One state at a time meant the county on the far side of the line — often the
 * nearest work there is — was simply not on the map.
 *
 * Only the states in play are fetched, which is usually two or three. Loading
 * all 3,144 counties would be over a megabyte and more Leaflet paths than a
 * laptop enjoys.
 *
 * ── THE MAP AND THE LIST ARE ONE SELECTION ─────────────────────────────────
 * Not a map with a list bolted on. A Leaflet polygon cannot be focused or
 * reached with a keyboard, so a map-only picker would lock out every keyboard
 * and screen reader user; the list is the accessible path and stays in sync
 * both ways. The map shows every state at once; the list shows one at a time,
 * because a flat list of six hundred counties is not a list anybody reads.
 *
 * ── "ALL OF <STATE>" IS PER STATE ──────────────────────────────────────────
 * Plenty of contractors genuinely cover a whole state, and making them tick
 * sixty-seven counties to say so is the kind of thing that ends a signup. It
 * is a choice about one state, not about the whole selection — covering all of
 * Delaware and three counties of Maryland is an ordinary thing to want.
 */
const StepAreas = ({ draft, update, next, back }) => {
  const [data, setData] = React.useState(null)
  const [failed, setFailed] = React.useState([])
  const [loading, setLoading] = React.useState(false)
  const [filter, setFilter] = React.useState("")

  const areas = draft.areas
  const states = areas.states || []
  const wholeStates = areas.wholeStates || []
  const focus = areas.focus || states[0] || ""
  const focusState = stateByCode(focus)

  /* One fetch per state, cached in the geo lib, merged into one collection. */
  React.useEffect(() => {
    if (states.length === 0) {
      setData(null)
      setFailed([])
      return undefined
    }
    let cancelled = false
    setLoading(true)

    loadCountiesFor(states)
      .then(result => {
        if (cancelled) return
        setData(result.collection)
        setFailed(result.failed)
        setLoading(false)
      })
      .catch(() => {
        if (!cancelled) setLoading(false)
      })

    return () => {
      cancelled = true
    }
  }, [states.join(",")]) // eslint-disable-line react-hooks/exhaustive-deps

  const setAreas = patch => update({ areas: { ...areas, ...patch } })

  const addState = code => {
    if (!code || states.includes(code)) return
    setAreas({ states: [...states, code], focus: code })
    setFilter("")
  }

  /**
   * Removing a state takes its counties with it.
   *
   * A GEOID left behind would keep the county in the service area with no way
   * to see or remove it — and it would still be on the published site.
   */
  const removeState = code => {
    const fips = fipsFor(code)
    const keptCounties = fips
      ? (areas.counties || []).filter(id => !id.startsWith(fips))
      : areas.counties || []
    const nextStates = states.filter(c => c !== code)
    setAreas({
      states: nextStates,
      wholeStates: wholeStates.filter(c => c !== code),
      counties: keptCounties,
      countyNames: countyNames(keptCounties),
      focus: focus === code ? nextStates[0] || "" : focus,
    })
  }

  const rowsFor = code => {
    const fips = fipsFor(code)
    if (!data || !fips) return []
    return sortedCounties({ type: "FeatureCollection", features: featuresForState(data, fips) })
  }

  const rows = rowsFor(focus)

  const toggleCounty = geoid => {
    // A county inside a whole-state selection is already covered; toggling it
    // individually would be a change with nothing to show for it.
    const fips = geoid.slice(0, 2)
    const owning = states.find(code => fipsFor(code) === fips)
    if (owning && wholeStates.includes(owning)) return

    const has = (areas.counties || []).includes(geoid)
    const nextIds = has
      ? areas.counties.filter(x => x !== geoid)
      : [...(areas.counties || []), geoid]
    setAreas({ counties: nextIds, countyNames: countyNames(nextIds) })
  }

  const toggleWholeState = (code, on) => {
    const fips = fipsFor(code)
    // Turning a whole state on clears that state's individual counties — they
    // are covered either way, and keeping both would mean removing the state
    // tick later silently restored a selection nobody remembers making.
    const keptCounties = on && fips
      ? (areas.counties || []).filter(id => !id.startsWith(fips))
      : areas.counties || []

    setAreas({
      wholeStates: on ? [...wholeStates, code] : wholeStates.filter(c => c !== code),
      counties: keptCounties,
      countyNames: countyNames(keptCounties),
    })
  }

  /* What the map draws as selected: the explicit counties, plus every county
     of a state that is covered whole. The map is a view of the selection, so
     it has to show the whole-state ones too. */
  const mapSelected = React.useMemo(() => {
    const out = new Set(areas.counties || [])
    for (const code of wholeStates) {
      const fips = fipsFor(code)
      if (!fips || !data) continue
      for (const feature of featuresForState(data, fips)) out.add(feature.properties.GEOID)
    }
    return [...out]
  }, [areas.counties, wholeStates, data])

  /** FIPS codes whose counties must not respond to a click on the map. */
  const lockedFips = wholeStates.map(code => fipsFor(code)).filter(Boolean)

  const visible = filter
    ? rows.filter(r => r.NAMELSAD.toLowerCase().includes(filter.toLowerCase()))
    : rows

  const chosen = wholeStates.length > 0 || (areas.counties || []).length > 0
  const available = US_STATES.filter(st => !states.includes(st.code))

  const countyCountIn = code => {
    const fips = fipsFor(code)
    if (!fips) return 0
    return (areas.counties || []).filter(id => id.startsWith(fips)).length
  }

  return (
    <div>
      <h1 className={s.question}>Where do you work?</h1>
      <p className={s.hint}>
        Pick the counties you cover. Click them on the map or tick them in the list — they are the
        same selection. Add more than one state if you work across a state line.
      </p>

      <div className={s.field} style={{ maxWidth: 340, marginBottom: 20 }}>
        <label htmlFor="area-state">{states.length ? "Add another state" : "Your state"}</label>
        <select
          id="area-state"
          className={s.select}
          value=""
          onChange={e => addState(e.target.value)}
        >
          <option value="">{states.length ? "Add a state…" : "Choose a state…"}</option>
          {available.map(st => (
            <option key={st.code} value={st.code}>
              {st.name}
            </option>
          ))}
        </select>
      </div>

      {failed.length > 0 ? (
        <p className={s.error}>
          {failed.length === 1
            ? `We could not load the counties for ${stateByCode(failed[0])?.name || failed[0]}.`
            : `We could not load the counties for ${failed.length} of the states you picked.`}{" "}
          Everything else still works — try removing and adding it again.
        </p>
      ) : null}

      {states.length > 0 ? (
        <div className={s.areaLayout}>
          <ServiceAreaMap
            data={data}
            selected={mapSelected}
            onToggle={toggleCounty}
            lockedFips={lockedFips}
            stateName={
              states.length === 1
                ? stateByCode(states[0])?.name || states[0]
                : `${states.length} states`
            }
          />

          <div className={s.countyPanel}>
            {/* One block per state: "which states do I cover?" is the question
                somebody is actually answering, and a flat list of six hundred
                counties does not answer it. */}
            <div className={s.stateList}>
              {states.map(code => {
                const st = stateByCode(code)
                const whole = wholeStates.includes(code)
                const picked = countyCountIn(code)
                return (
                  <div
                    key={code}
                    className={`${s.stateRow} ${focus === code ? s.stateRowOn : ""}`}
                  >
                    <label className={s.stateWhole}>
                      <input
                        type="checkbox"
                        checked={whole}
                        onChange={e => toggleWholeState(code, e.target.checked)}
                      />
                      All of {st ? st.name : code}
                    </label>

                    <button
                      type="button"
                      className={s.stateCount}
                      aria-pressed={focus === code}
                      onClick={() => {
                        setAreas({ focus: code })
                        setFilter("")
                      }}
                    >
                      {whole ? "every county" : `${picked} of ${rowsFor(code).length}`}
                    </button>

                    <button
                      type="button"
                      className={s.stateRemove}
                      aria-label={`Remove ${st ? st.name : code}`}
                      onClick={() => removeState(code)}
                    >
                      ×
                    </button>
                  </div>
                )
              })}
            </div>

            {focus && !wholeStates.includes(focus) ? (
              <>
                <div style={{ padding: "10px 12px 0" }}>
                  <input
                    className={s.input}
                    value={filter}
                    onChange={e => setFilter(e.target.value)}
                    placeholder={`Find a county in ${focusState ? focusState.name : focus}…`}
                    aria-label="Filter counties"
                  />
                </div>
                <div className={s.countyList}>
                  {visible.map(row => (
                    <label key={row.GEOID} className={s.countyItem}>
                      <input
                        type="checkbox"
                        checked={(areas.counties || []).includes(row.GEOID)}
                        onChange={() => toggleCounty(row.GEOID)}
                      />
                      {row.NAMELSAD}
                    </label>
                  ))}
                  {data && !loading && visible.length === 0 ? (
                    <p style={{ padding: 12, fontSize: 13, color: "var(--muted)" }}>
                      {filter ? `Nothing matches “${filter}”.` : "No counties to show."}
                    </p>
                  ) : null}
                  {loading ? (
                    <p style={{ padding: 12, fontSize: 13, color: "var(--muted)" }}>Loading…</p>
                  ) : null}
                </div>
              </>
            ) : (
              <p className={s.countyNote}>
                {focus
                  ? `Every county in ${focusState ? focusState.name : focus} is covered.`
                  : "Pick a state above to choose counties."}
              </p>
            )}
          </div>
        </div>
      ) : null}

      <div className={s.actions}>
        <button type="button" className={s.back} onClick={back}>
          Back
        </button>
        <button
          type="button"
          className={`btn btn--lg ${s.spacer}`}
          disabled={!chosen}
          onClick={next}
        >
          {draft.generated ? "Back to my website" : "Generate my website"}
          <ArrowRight className="btn__arrow" />
        </button>
      </div>
    </div>
  )
}

export default StepAreas
