import * as React from "react"
import { TEMPLATE_TIERS, templatesForTier, templateById } from "../../data/site-templates"
import * as s from "./Builder.module.css"

/**
 * Stepping through page templates — MTC-FCS-016.
 * ============================================================================
 * Left and right arrows either side of the template's name; the preview
 * changes as they are pressed.
 *
 * ── ARROWS, NOT A GRID OF SIX THUMBNAILS ───────────────────────────────────
 * The preview is already on screen at full size and updates instantly, so a
 * grid of postage-stamp screenshots would be a worse picture of the same thing
 * next to a better one. Arrows also mean somebody can simply press through all
 * four and stop at the one they like without deciding anything in advance.
 *
 * ── IT WRAPS ───────────────────────────────────────────────────────────────
 * Right from the last goes back to the first. A dead arrow at each end turns
 * "press through them" into "press through them and then notice nothing
 * happened", and there is no order to lose your place in.
 *
 * ── THE DOTS ARE BUTTONS ───────────────────────────────────────────────────
 * Four is few enough to jump between, and having gone forwards past the one
 * you wanted, going straight back to it beats three more presses.
 *
 * ── TWO SHAPES, ONE CONTROL — MTC-FCS-023 ──────────────────────────────────
 * `inline` lays it out as a bar directly above the preview rather than as a
 * card in the side column, which is where it lives now. Buried among the other
 * options it read as one more setting; the whole point of it is that somebody
 * presses an arrow and watches the page change, so it belongs next to the
 * page. Same markup and the same behaviour either way — only the arrangement
 * differs, so there is no second version of this to keep working.
 */

const Chevron = ({ back }) => (
  <svg
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="2.2"
    strokeLinecap="round"
    strokeLinejoin="round"
    aria-hidden="true"
  >
    <path d={back ? "m15 5-7 7 7 7" : "m9 5 7 7-7 7"} />
  </svg>
)

const TemplatePicker = ({ value, onChange, inline = false, plan = "free" }) => {
  const current = templateById(value)

  /* ── ONE GROUP PER TIER — FCS-077 ─────────────────────────────────────
     The arrows used to walk all seven designs, so somebody on Premium
     flicked past Lead Generation ones they could not have, and the count
     ("3 of 7") described a list they were not really choosing from.

     The group follows the PLAN, not the design currently showing. Keying it
     to the design looked right and trapped people: a Free plan starts on
     Classic, Classic is the only Free design, and the arrows then had
     nowhere to go — the other six were unreachable from the one screen
     meant for choosing between them. Changing the plan changes the group,
     which is also how somebody discovers what the paid tiers look like. */
  const group = templatesForTier(plan)
  const tier = TEMPLATE_TIERS.find(t => t.id === plan)
  const index = group.findIndex(template => template.id === current.id)
  const total = group.length

  /* ── THE SELECTION FOLLOWS THE GROUP ─────────────────────────────────
     The chosen design is not in this plan's group, which happens the moment
     somebody switches plan. Move the selection to the first design of the
     new group rather than leaving it pointing outside: the bar was naming
     one design while the dots counted a set that did not contain it, and
     the first press of Next skipped whatever was at the front.

     Shown, NOT written. Changing the draft here would throw away a choice
     somebody made: MTC-FCS-016 keeps a premium design on the draft while
     they look at Free, so dropping down to compare and coming back restores
     it. Rewriting the selection on every plan change deleted that. The bar
     points at the front of the group, the draft keeps what it had, and the
     next arrow or dot is the explicit choice. */
  const position = index === -1 ? 0 : index
  const showing = group[position] || current

  const step = delta => {
    // +total before the modulo: JavaScript's % keeps the sign, so -1 % 4 is
    // -1 and stepping left off the first template would land nowhere.
    const next = (position + delta + total) % total
    onChange(group[next].id)
  }

  const prev = (
    <button
      type="button"
      className={s.traverseArrow}
      aria-label="Previous template"
      onClick={() => step(-1)}
    >
      <Chevron back />
    </button>
  )

  const next = (
    <button
      type="button"
      className={s.traverseArrow}
      aria-label="Next template"
      onClick={() => step(1)}
    >
      <Chevron />
    </button>
  )

  const dots = (
    <div className={s.traverseDots} role="tablist" aria-label="Template">
      {group.map((template, i) => (
        <button
          key={template.id}
          type="button"
          role="tab"
          aria-selected={i === position}
          aria-label={template.label}
          className={`${s.traverseDot} ${i === position ? s.traverseDotOn : ""}`}
          onClick={() => onChange(template.id)}
        />
      ))}
    </div>
  )

  if (inline) {
    return (
      <div className={s.traverseBar}>
        {prev}
        <span className={s.traverseBarBody} aria-live="polite">
          <span className={s.traverseBarTop}>
            <span className={s.traverseName}>{showing.label}</span>
            <span className={s.traverseCount}>
              {tier ? `${tier.label} · ` : ""}
              {position + 1} of {total}
            </span>
          </span>
          <span className={s.traverseBlurb}>{showing.blurb}</span>
        </span>
        {dots}
        {next}
      </div>
    )
  }

  return (
    <div className={s.panel}>
      <p className={s.panelTitle}>Page template</p>

      <div className={s.traverse}>
        {prev}
        <span className={s.traverseBody} aria-live="polite">
          <span className={s.traverseName}>{showing.label}</span>
          <span className={s.traverseBlurb}>{showing.blurb}</span>
          <span className={s.traverseCount}>
            {index + 1} of {total}
          </span>
        </span>
        {next}
      </div>

      {dots}
    </div>
  )
}

export default TemplatePicker
