import * as React from "react"
import { TRADES } from "../../data/trades"
import TradeIcon from "./TradeIcon"
import { ArrowRight } from "../Icons"
import * as s from "./Builder.module.css"

/**
 * Question one: what kind of contracting work do you do?
 *
 * One choice, asked on its own screen. The trade decides which services get
 * offered next and which glyph the generated site carries, so asking it
 * alongside anything else would mean rebuilding the next screen mid-answer.
 *
 * Picking a trade advances immediately — there is nothing else on this screen
 * to fill in, and a Continue button that only ever confirms the click you just
 * made is a second click for no information.
 */
const StepTrade = ({ draft, update, next }) => {
  const choose = slug => {
    // Changing trade invalidates services picked from the old one. Silently
    // keeping "Roof Repair" under Plumbing would be worse than clearing it.
    const changed = slug !== draft.tradeSlug
    update({
      tradeSlug: slug,
      services: changed ? [] : draft.services,
      serviceCopy: changed ? {} : draft.serviceCopy,
    })
    next()
  }

  return (
    <div>
      <h1 className={s.question}>What kind of contracting work do you do?</h1>
      <p className={s.hint}>
        This sets up the rest of the questions and picks the starting look for your site. You can
        change it later.
      </p>

      <div className={s.tradeGrid}>
        {TRADES.map(trade => (
          <button
            key={trade.slug}
            type="button"
            onClick={() => choose(trade.slug)}
            className={`${s.tradeCard} ${draft.tradeSlug === trade.slug ? s.tradeCardOn : ""}`}
          >
            <span className={s.tradeMark}>
              <TradeIcon name={trade.icon} />
            </span>
            <span>
              <span className={s.tradeName}>{trade.name}</span>
              <span className={s.tradeBlurb}>{trade.description}</span>
            </span>
          </button>
        ))}
      </div>

      <div className={s.actions}>
        <button
          type="button"
          className="btn btn--lg"
          disabled={!draft.tradeSlug}
          onClick={next}
        >
          Continue
          <ArrowRight className="btn__arrow" />
        </button>
      </div>
    </div>
  )
}

export default StepTrade
