import { apiUrl } from "../config/api"
import { SUPABASE_PUBLISHABLE_KEY } from "../config/supabase-public"
import { supabase } from "./supabase"
import { collectSiteCss, renderSiteDocument } from "./site-export"

/**
 * Hand the finished website to the server BEFORE paying for it — FCS-125.
 * ============================================================================
 * The page only exists in this browser. If publishing it waits until the customer is back from Stripe, a customer who closes the tab
 * on the way back has paid for a website that nothing ever makes. So the builder saves it first, and the Stripe webhook publishes and
 * builds the address the moment the payment lands, whether or not anybody is looking (functions/stage-site, _shared/finalize.ts).
 *
 *   1. stage-site "content"   the draft goes up, its photographs are moved into Storage, and the server answers with the published
 *                             shape of the site (photographs as addresses instead of data)
 *   2. the page is drawn here from THAT, exactly as the live site and the address's repository are drawn from the published file, so
 *      what is saved is what will be live (the templates' styles can only be collected in a browser)
 *   3. stage-site "html"      the drawn page goes up
 *
 * Nothing staged is live and nobody is charged. Returns { ok: true } or { ok: false, message } and never throws: the caller stops
 * before Stripe on a failure, because a payment that could not be turned into a website is the one thing this must prevent.
 */

const FAILED = "We could not save your website just now. Nothing was charged. Please try again in a moment."

async function call(body) {
  const client = supabase()
  const { data } = client ? await client.auth.getSession() : { data: null }
  const res = await fetch(apiUrl("stage-site"), {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      apikey: SUPABASE_PUBLISHABLE_KEY,
      Authorization: `Bearer ${data?.session?.access_token || SUPABASE_PUBLISHABLE_KEY}`,
    },
    body: JSON.stringify(body),
  })
  return { status: res.status, body: await res.json().catch(() => ({})) }
}

export async function stageSite({ draft, slug, plan }) {
  try {
    const saved = await call({ action: "content", slug, plan, draft })
    if (saved.status !== 200 || !saved.body.site) return { ok: false, message: saved.body.message || FAILED }

    let html = ""
    try {
      html = renderSiteDocument(saved.body.site.content, collectSiteCss(), { plan: saved.body.site.plan })
    } catch {
      return { ok: false, message: "We could not prepare your page. Nothing was charged. Please try again." }
    }

    const page = await call({ action: "html", slug, html })
    if (page.status !== 200) return { ok: false, message: page.body.message || FAILED }
    return { ok: true }
  } catch {
    return { ok: false, message: FAILED }
  }
}
