/** Both files are derived from the id — one place decides what they are called. */
export const galleryFiles = item => ({
  file: `${item.id}.avif`,
  thumb: `${item.id}-thumb.avif`,
})

const withFiles = GALLERY.map(item => ({ ...item, ...galleryFiles(item) }))

/**
 * The dropdown: "All", then only the trades that actually have pictures.
 *
 * Offering a category that turns out to be empty is a promise the grid cannot
 * keep, and while this gallery is being filled in most of them will be.
 */
export const GALLERY_CATEGORIES = [
  { id: "all", label: "All" },
  ...TRADES.filter(trade => withFiles.some(item => item.trades.includes(trade.slug))).map(
    trade => ({ id: trade.slug, label: trade.name })
  ),
]

export function galleryFor(category) {
  if (!category || category === "all") return withFiles
  return withFiles.filter(item => item.trades.includes(category))
}
