import * as React from "react"
import { CUSTOM_DOMAIN_NOTE, DEFAULT_PAID_PLAN, formatMoney, planById } from "../../config/pricing"
import { LEVELS, levelsForTier } from "../../data/plans"
import { downloadSite } from "../../lib/site-export"
import { stageSite } from "../../lib/stage-site"
import { PREMIUM_SECTIONS } from "../../data/premium"
import { apiUrl } from "../../config/api"
import { useSubdomain } from "../../lib/use-subdomain"
import { SUPABASE_PUBLISHABLE_KEY } from "../../config/supabase-public"
import { activeExtras, activeTemplate, benefitPatch } from "../../lib/site-draft"
import { slugify, slugProblem } from "../../lib/slug"
import { ArrowRight, Check } from "../Icons"
import { Link, navigate } from "gatsby"
import { accessToken, useAuth } from "../../context/auth"
import { configured as accountsConfigured, supabase } from "../../lib/supabase"
import * as s from "./Builder.module.css"

/**
 * Checkout — the details we need, then Stripe for the ones we must not touch.
 *
 * ── NO CARD FIELDS ON THIS PAGE, EVER ──────────────────────────────────────
 * Name, business address and email are collected here because they are ours to
 * hold: they go on the invoice and on the site's contact details. A card
 * number is not. Putting one card input on this page drags the whole site into
 * PCI DSS scope, so payment happens on Stripe's own checkout and this form
 * hands off before a card is ever typed.
 *
 * ── A PAYMENT NEEDS AN OWNER ───────────────────────────────────────────────
 * Building is anonymous on purpose: asking for an account before somebody has
 * seen their website is how a free funnel stops being free to enter. Paying is
 * different. Without a signed-in account there is nobody to attach the
 * subscription to, nobody to show the site to afterwards, and no answer to
 * "is this mine?" beyond an email address anybody could type — so the request
 * carries the session token, and this screen asks for an account first when
 * there is none.
 *
 * The token is VERIFIED server-side against Supabase. Nothing here is trusted
 * to say who the buyer is; the route looks it up.
 *
 * ── WHAT HAPPENS WHEN STRIPE IS NOT CONFIGURED ─────────────────────────────
 * The API route says so, plainly, and the screen repeats it. It does not
 * pretend to take a payment and it does not silently mark the site as live —
 * a fake success page is the one outcome that costs somebody real money to
 * untangle later.
 */
const StepCheckout = ({ draft, update, back, goTo }) => {
  const { user, ready: sessionReady, available: accountsAvailable } = useAuth()
  const [billing, setBilling] = React.useState({
    contactName: "",
    line1: "",
    line2: "",
    city: "",
    // The first state they work in is the likeliest billing state — a
    // guess they can change, not an answer. MTC-FCS-026.
    state: (draft.areas.states || [])[0] || "",
    postalCode: "",
    email: draft.business.email || "",
  })
  const [busy, setBusy] = React.useState(false)
  const [error, setError] = React.useState("")

  const set = (key, value) => setBilling(prev => ({ ...prev, [key]: value }))

  // The address is chosen here, not derived silently, because it is fixed at
  // checkout: the Stripe session carries it and the publish route refuses to
  // put a paid order anywhere else.
  const [slug, setSlug] = React.useState(
    () => draft.slug || slugify(draft.business.name) || "my-business"
  )
  const slugError = slugProblem(slug)

  /* ── The address, and whether anybody else has it — FCS-059 ───────────── */
  const availability = useSubdomain(slug)

  const slugMessage =
    availability.status === "checking"
      ? "Checking if that address is free…"
      : availability.status === "available"
        ? `${slug}.freecontractorservices.com is free.`
        : availability.reason ||
          "This is where your site will live. It cannot be changed after checkout."

  /* "We could not check" is a warning, not an error: it must not look like a
     refusal, because nothing was refused. */
  const slugTone =
    availability.status === "taken" || availability.status === "invalid"
      ? s.error
      : availability.status === "available"
        ? s.ok
        : s.fieldNote

  /* What is being bought — MTC-FCS-015. The plan is the contractor's choice
     from the previous screen; the route re-reads its price from the same
     config rather than trusting an amount from here. Only the sections that
     will ACTUALLY render are listed: promising a gallery that is switched on
     but empty would be charging for a heading. */
  const plan = planById(draft.plan)
  const extras = activeExtras(draft, plan.id)
  const extraSections = PREMIUM_SECTIONS.filter(section => extras[section.id])
  const template = activeTemplate(draft, plan.id)

  /** Every benefit id a tier includes, all ticked. */
  const allOf = tierId =>
    LEVELS.reduce((acc, level) => {
      const inTier = planById(tierId).levels.includes(level.id)
      for (const item of level.items) acc[item.id] = inTier
      return acc
    }, {})
  // What this order actually includes, straight off the benefit list — and
  // only the ones still ticked, so an unticked benefit is not billed as
  // delivered.
  const included = levelsForTier(plan.id).flatMap(level =>
    level.items.filter(item => draft.benefits?.[item.id] || (item.id === "gallery" && draft.extras?.gallery) || (item.id === "leadform" && draft.extras?.leadform))
  )

  const ready =
    billing.contactName.trim() &&
    billing.line1.trim() &&
    billing.city.trim() &&
    billing.postalCode.trim() &&
    /.+@.+\..+/.test(billing.email) &&
    /* Only a CONFIRMED refusal stops the payment — FCS-059. Blocking while
       the check is in flight disables the button under the cursor of anybody
       who types their address and clicks straight through, which is most
       people; the check settles half a second later and they have already
       decided the site is broken. "Taken" is the answer worth stopping for,
       and the database's unique constraint is what actually guarantees it. */
    !slugError &&
    availability.status !== "taken"

  const submit = async e => {
    e.preventDefault()
    // No account, no payment: see the note at the top. The gate below means
    // this should be unreachable, which is exactly why it is worth keeping.
    if (!ready || busy || !user) return
    setBusy(true)
    setError("")

    // The email typed here is the one that will receive the receipt, so it is
    // also the one the site should show. Keeping them in step here avoids a
    // published site whose contact address nobody reads.
    // Both of these have to be on the draft before the browser leaves for
    // Stripe: the success page reads them back to publish, and it is a
    // different page load with nothing but localStorage to go on.
    update({
      slug,
      business: { ...draft.business, email: billing.email || draft.business.email },
    })

    try {
      /* ── NO ACCOUNT IS REQUIRED TO GET THIS FAR — FCS-055 ──────────────
         Signing in used to be the price of reaching Stripe. It is not any
         more: somebody who has just built a website should be able to pay
         for it. The token is sent when there is one, and when there is not,
         create-checkout-session mints an anonymous account at that moment
         and hands the session back below — so the purchase belongs to
         somebody from the instant it exists, and they can claim it with an
         email address afterwards. */
      const token = await accessToken()

      const res = await fetch(apiUrl("create-checkout-session"), {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          apikey: SUPABASE_PUBLISHABLE_KEY,
          Authorization: `Bearer ${token || SUPABASE_PUBLISHABLE_KEY}`,
        },
        body: JSON.stringify({
          billing,
          plan: plan.id,
          site: {
            subdomain: slug,
            businessName: draft.business.name.trim(),
            trade: draft.tradeSlug,
            services: draft.services,
          },
        }),
      })

      const data = await res.json().catch(() => ({}))

      if (!res.ok) {
        setError(data.message || "Checkout could not be started. Please try again.")
        setBusy(false)
        return
      }

      if (data.url) {
        /* Adopt the identity the purchase was attached to, BEFORE leaving for
           Stripe. Without this the buyer comes back as a different anonymous
           nobody and the site they paid for belongs to a user id the browser
           has never heard of. */
        if (data.session?.access_token) {
          const client = supabase()
          if (client) {
            await client.auth.setSession({
              access_token: data.session.access_token,
              refresh_token: data.session.refresh_token,
            })
          }
        }

        /* SAVE THE WEBSITE BEFORE LEAVING — FCS-125. The page exists only in this browser. Saved now, the payment alone is enough:
           the webhook publishes it and builds the address even if this tab is closed on the way back from Stripe. If it cannot be
           saved the customer stays here, uncharged, rather than paying for something nothing will make. */
        const staged = await stageSite({
          draft: { ...draft, slug, business: { ...draft.business, email: billing.email || draft.business.email } },
          slug,
          plan: plan.id,
        })
        if (!staged.ok) {
          setError(staged.message)
          setBusy(false)
          return
        }

        window.location.href = data.url
        return
      }

      setError(data.message || "Checkout is not configured yet, so no payment was taken.")
      setBusy(false)
    } catch {
      setError("We could not reach the payment service. Check your connection and try again.")
      setBusy(false)
    }
  }

  /* Free has nothing to charge, so there is nothing for this screen to do.
     Rather than open a Stripe session for $0 — which would take a card, send a
     receipt for nothing, and leave a subscription to cancel — it says where
     hosting actually starts and offers the two honest ways forward. */
  if (plan.id === "free") {
    return (
      <div>
        <h1 className={s.question}>Putting it online</h1>
        <p className={s.hint}>
          Your website is finished and it is yours. Hosting it at your own address is the part
          that costs something.
        </p>

        <div className={s.freeGate}>
          <p className={s.freeGateLead}>
            <strong>{DEFAULT_PAID_PLAN.name}</strong> is{" "}
            {formatMoney(DEFAULT_PAID_PLAN.amount, DEFAULT_PAID_PLAN.currency)} a month with no
            contract, and puts your site on your own address with your own branding only.
          </p>

          <ul className="checks" style={{ marginBottom: 22 }}>
            {levelsForTier(DEFAULT_PAID_PLAN.id)
              .flatMap(level => level.items)
              .map(item => (
                <li key={item.id} style={{ fontSize: 13.5 }}>
                  <Check />
                  {item.label}
                </li>
              ))}
          </ul>

          <div className={s.freeGateActions}>
            <button
              type="button"
              className="btn btn--lg"
              onClick={() => {
                update({ plan: DEFAULT_PAID_PLAN.id, ...benefitPatch(draft, allOf(DEFAULT_PAID_PLAN.id)) })
                if (goTo) goTo(4)
              }}
            >
              Choose {DEFAULT_PAID_PLAN.name}
              <ArrowRight className="btn__arrow" />
            </button>
            <button type="button" className={s.back} onClick={() => downloadSite(draft)}>
              Download the page instead
            </button>
          </div>

          <p className={s.fieldNote} style={{ marginTop: 18 }}>
            The downloaded page is a complete website you can host anywhere. It is always the
            free version: a small FreeContractorServices credit in the footer, and none of the
            Premium sections or designs.
          </p>
        </div>

        <div className={s.actions}>
          <button type="button" className={s.back} onClick={back}>
            Back
          </button>
        </div>
      </div>
    )
  }

  /* ── An account first, for paid tiers only ─────────────────────────────
     Free takes no payment and hands over a file, so it is handled above and
     never reaches this. Everything below is a purchase. */
  if (accountsConfigured() && accountsAvailable && sessionReady && !user) {
    return (
      <div>
        <h1 className={s.question}>One thing first</h1>
        <p className={s.hint}>
          Your website is saved and waiting. A subscription needs an owner — somebody to send
          the receipt to, somebody who can cancel it, and somebody the site belongs to when you
          come back to it. It takes about a minute.
        </p>

        <div className={s.freeGate}>
          <p className={s.freeGateLead}>
            <strong>Nothing you have built is lost.</strong> Create an account or log in, and you
            will come straight back here with your website exactly as you left it.
          </p>

          <div className={s.freeGateActions}>
            <Link to="/sign-up?next=/website-builder" className="btn btn--lg">
              Create an account
              <ArrowRight className="btn__arrow" />
            </Link>
            <button
              type="button"
              className={s.back}
              onClick={() => navigate("/log-in?next=/website-builder")}
            >
              I already have one
            </button>
          </div>
        </div>

        <div className={s.actions}>
          <button type="button" className={s.back} onClick={back}>
            Back
          </button>
        </div>
      </div>
    )
  }

  if (accountsConfigured() && accountsAvailable && !sessionReady) {
    return (
      <div>
        <h1 className={s.question}>Put your site online</h1>
        <p className={s.hint}>Just a moment…</p>
      </div>
    )
  }

  return (
    <div>
      <h1 className={s.question}>Put your site online</h1>
      <p className={s.hint}>
        We need a few details for your receipt and your site&rsquo;s contact information. Payment
        happens on Stripe — no card details are typed on this page.
      </p>

      <form className={s.checkout} onSubmit={submit}>
        <div className={s.fields} style={{ maxWidth: "none" }}>
          <div className={s.fieldRow}>
            <div className={s.field}>
              <label htmlFor="co-name">Your name</label>
              <input
                id="co-name"
                value={billing.contactName}
                onChange={e => set("contactName", e.target.value)}
                autoComplete="name"
                required
              />
            </div>
            <div className={s.field}>
              <label htmlFor="co-email">Email address</label>
              <input
                id="co-email"
                type="email"
                value={billing.email}
                onChange={e => set("email", e.target.value)}
                autoComplete="email"
                required
              />
              <p className={s.fieldNote}>Your receipt and site details go here.</p>
            </div>
          </div>

          <div className={s.field}>
            <label htmlFor="co-line1">Business address</label>
            <input
              id="co-line1"
              value={billing.line1}
              onChange={e => set("line1", e.target.value)}
              autoComplete="address-line1"
              placeholder="Street address"
              required
            />
          </div>

          <div className={s.field}>
            <label htmlFor="co-line2">Apartment, suite, unit (optional)</label>
            <input
              id="co-line2"
              value={billing.line2}
              onChange={e => set("line2", e.target.value)}
              autoComplete="address-line2"
            />
          </div>

          <div className={s.field}>
            <label htmlFor="co-slug">Your website address</label>
            <div className={s.slugRow}>
              <input
                id="co-slug"
                value={slug}
                onChange={e => setSlug(slugify(e.target.value))}
                maxLength={50}
                aria-invalid={slugError ? "true" : undefined}
              />
              <span>.freecontractorservices.com</span>
            </div>
            {/* ── IS IT FREE? — FCS-059 ──────────────────────────────────
                Asked while they type, so the answer lands before the payment
                rather than after it. `availability` never says "free" when it
                could not reach the check — see lib/use-subdomain.js. */}
            <p className={slugTone} data-state={availability.status}>
              {slugMessage}
            </p>
            {/* Said here as well as in the summary: the moment somebody worries
                about their domain is the moment they are typing this field,
                not when they glance at the order panel. */}
            <p className={s.fieldNote}>{CUSTOM_DOMAIN_NOTE}</p>
          </div>

          <div className={s.fieldRow}>
            <div className={s.field}>
              <label htmlFor="co-city">City</label>
              <input
                id="co-city"
                value={billing.city}
                onChange={e => set("city", e.target.value)}
                autoComplete="address-level2"
                required
              />
            </div>
            <div className={s.field}>
              <label htmlFor="co-postal">ZIP code</label>
              <input
                id="co-postal"
                value={billing.postalCode}
                onChange={e => set("postalCode", e.target.value)}
                autoComplete="postal-code"
                required
              />
            </div>
          </div>
        </div>

        <div>
          <div className={s.summary}>
            <p className={s.panelTitle}>Your order</p>

            <div className={s.summaryLine}>
              <span>{plan.name}</span>
              <span>
                {formatMoney(plan.amount, plan.currency)}/{plan.interval}
              </span>
            </div>
            <div className={s.summaryLine}>
              <span>Website design</span>
              <span style={{ color: "var(--green)", fontWeight: 600 }}>Free</span>
            </div>
            <div className={s.summaryLine}>
              <span>Your address</span>
              <span style={{ color: "var(--muted)", fontSize: 13 }}>
                {slug}.freecontractorservices.com
              </span>
            </div>

            {plan.id === "premium" ? (
              <div className={s.summaryLine}>
                <span>Page template</span>
                <span style={{ color: "var(--muted)", fontSize: 13 }}>{template.label}</span>
              </div>
            ) : null}

            {plan.id === "premium" ? (
              <div className={s.summaryLine} style={{ alignItems: "flex-start" }}>
                <span>Premium sections</span>
                <span style={{ color: "var(--muted)", fontSize: 13, textAlign: "right" }}>
                  {extraSections.length > 0
                    ? extraSections.map(section => section.label).join(", ")
                    : "None added yet"}
                </span>
              </div>
            ) : null}

            <p className={s.summaryNote}>{CUSTOM_DOMAIN_NOTE}</p>

            <div className={s.summaryTotal}>
              <span>Due today</span>
              <span>{formatMoney(plan.amount, plan.currency)}</span>
            </div>

            <ul className="checks" style={{ marginTop: 18 }}>
              {included.map(item => (
                <li key={item.id} style={{ fontSize: 13.5 }}>
                  <Check />
                  {item.label}
                </li>
              ))}
            </ul>

            <button
              type="submit"
              className="btn btn--lg"
              style={{ width: "100%", justifyContent: "center", marginTop: 20 }}
              disabled={!ready || busy}
            >
              {busy ? "Starting checkout…" : "Continue to secure payment"}
              {!busy && <ArrowRight className="btn__arrow" />}
            </button>

            <p className={s.secureNote}>
              You will be taken to Stripe to pay. We never see or store your card details. Cancel
              any time from your receipt email.
            </p>

            {error ? <p className={s.error}>{error}</p> : null}
          </div>

          <div className={s.actions} style={{ marginTop: 18 }}>
            <button type="button" className={s.back} onClick={back}>
              Back to editing
            </button>
          </div>
        </div>
      </form>
    </div>
  )
}

export default StepCheckout
