import * as React from "react"
import { renderToStaticMarkup } from "react-dom/server"
import GeneratedSite from "../components/builder/GeneratedSite"
import { themeById } from "./site-draft"

/**
 * Turning a draft into a publishable HTML file — MTC-FCS-002.
 * ============================================================================
 *
 * ── THE SAME COMPONENT THE PREVIEW USES ────────────────────────────────────
 * This renders GeneratedSite with the draft and inlines the rules that the
 * page is already using. There is no second "published" implementation,
 * because two renderers drift and the published site is the one nobody is
 * watching.
 *
 * ── THE CSS IS READ BACK OFF THE PAGE, NOT RE-AUTHORED ─────────────────────
 * CSS Modules hash their class names at build time, so the exported markup
 * carries names like `GeneratedSite-module--hero--a1b2` that only the compiled
 * stylesheet knows. Rather than maintain a duplicate stylesheet that would
 * quietly fall out of step, this walks document.styleSheets and takes the
 * rules whose selectors mention that module — including the ones nested in
 * @media blocks, which is what makes the exported page responsive.
 *
 * The alternative, a hand-written copy of the same CSS, is exactly the drift
 * this file exists to avoid.
 *
 * ── ONE FILE, NO JAVASCRIPT ────────────────────────────────────────────────
 * Everything is inline: no build step, no CDN for CSS, nothing to break at
 * render time. Fonts come from Google Fonts with a real fallback stack, so the
 * page is readable before (and without) them. Uploaded photographs are already
 * data URLs on the draft, so they travel inside the file too.
 */

const MODULE_MARK = "GeneratedSite-module--"

/**
 * Every rule belonging to the generated site, in source order.
 *
 * Cross-origin stylesheets throw on `.cssRules`; those are skipped rather than
 * allowed to abort the export.
 */
export function collectSiteCss() {
  if (typeof document === "undefined") return ""
  const out = []

  /* The ported templates (MTC-FCS-041) style themselves with global class
     names from the Mockup Maker's own stylesheets, so those have to survive
     the filter too — otherwise the preview and the download are unstyled. */
  /* `tm` and `wtm` are the classes of the designs composed in the Template Maker (src/templates/runtime): without them in this list
     the published page of such a design had its markup and none of its styling. (FCS-124) */
  const wanted = selector =>
    selector.includes(MODULE_MARK) || /(^|[\s,>~+(])\.(mk|v2|v3|clean|studio|signature|tm|wtm)[-\s.,:[]/.test(selector) ||
    /(^|[\s,>~+(])\.(mk|v2|v3|clean|studio|signature|tm|wtm)$/.test(selector)

  const take = rule => {
    // Plain style rule — keep it if it targets the module or a template.
    if (rule.selectorText) {
      if (wanted(rule.selectorText)) out.push(rule.cssText)
      return
    }
    // @media / @supports — recurse, and keep the wrapper only if it had
    // anything worth keeping. This is where the responsive behaviour lives.
    if (rule.cssRules) {
      const inner = []
      for (const child of rule.cssRules) {
        if (child.selectorText && wanted(child.selectorText)) {
          inner.push(child.cssText)
        }
      }
      if (inner.length > 0) {
        const condition = rule.conditionText || rule.media?.mediaText || ""
        const at = rule.type === 12 ? "@supports" : "@media"
        out.push(`${at} ${condition} {\n${inner.join("\n")}\n}`)
      }
    }
  }

  for (const sheet of Array.from(document.styleSheets)) {
    let rules
    try {
      rules = sheet.cssRules
    } catch {
      continue // cross-origin, nothing readable here
    }
    if (!rules) continue

    /* ── A template's own stylesheet is taken WHOLE — MTC-FCS-041 ───────
       The ported designs ship the Mockup Maker's stylesheets, and those do
       more than style `.mk` classes: they reset links, box sizing and list
       markers for the document they are drawn into. Filtering them
       selector-by-selector kept the layout and dropped the resets, which is
       how the first port came out with browser-default underlines on every
       link. So: if a sheet defines the template root, everything in it is
       part of that design. */
    const list = Array.from(rules)
    const isTemplateSheet = list.some(
      rule => rule.selectorText && /(^|[\s,])\.mk(\b|[-.])/.test(rule.selectorText)
    )
    if (isTemplateSheet) {
      for (const rule of list) out.push(rule.cssText)
      continue
    }

    for (const rule of list) take(rule)
  }

  return out.join("\n")
}

const escapeHtml = value =>
  String(value == null ? "" : value)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")

/** The site's address, derived from the business name. */
export function slugFor(draft) {
  const base = (draft.business.name || "").trim().toLowerCase()
  const slug = base
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 50)
  return slug || "my-business"
}

/**
 * The finished document.
 *
 * `css` is passed in rather than collected here so a caller can render the
 * same draft several times without re-walking every stylesheet.
 */
export function renderSiteDocument(draft, css = collectSiteCss(), { plan } = {}) {
  // `plan` overrides what the draft says, which is how the publish path hands
  // over the tier that was actually PAID for and how the download hands over
  // the free one. Left out, the draft's own choice wins — that is the preview.
  const body = renderToStaticMarkup(React.createElement(GeneratedSite, { draft, plan }))

  const name = draft.business.name.trim() || "Contractor"
  const description =
    draft.business.tagline.trim() ||
    (draft.business.about.trim() ? draft.business.about.trim().slice(0, 155) : `${name} — get a free quote.`)

  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escapeHtml(name)}</title>
<meta name="description" content="${escapeHtml(description)}">
<meta property="og:title" content="${escapeHtml(name)}">
<meta property="og:description" content="${escapeHtml(description)}">
<meta property="og:type" content="website">
<meta name="theme-color" content="${escapeHtml(themeById(draft.themeId).primary)}">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&family=Poppins:wght@600;700;800&display=swap" rel="stylesheet">
<style>
*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%;scroll-behavior:smooth}
body{margin:0;background:#fff}
img{display:block;max-width:100%}
a{color:inherit}
${css}
</style>
</head>
<body>
${body}
</body>
</html>`
}

/** Hands the finished file to the browser as a download. */
/**
 * The downloaded file is always the FREE version — MTC-FCS-025.
 *
 * Classic template, no premium sections, the FreeContractorServices credit in
 * the footer. Handing somebody a premium page as a file they can host anywhere
 * would be giving the paid tier away with a download button, and the button is
 * on the screen where they are deciding whether to pay for it.
 *
 * It is the same rule the publish route enforces server-side, applied here at
 * the only other place a page leaves the builder.
 */
export function downloadSite(draft) {
  const html = renderSiteDocument(draft, collectSiteCss(), { plan: "free" })
  const blob = new Blob([html], { type: "text/html;charset=utf-8" })
  const url = URL.createObjectURL(blob)
  const a = document.createElement("a")
  a.href = url
  a.download = `${slugFor(draft)}.html`
  document.body.appendChild(a)
  a.click()
  a.remove()
  // Revoking immediately can cancel the download in some browsers.
  setTimeout(() => URL.revokeObjectURL(url), 4000)
  return html
}
