import * as React from "react"
import { copyVariants } from "../../data/service-copy"
import { describeOptions, describeService } from "../../lib/site-draft"
import { ArrowRight, Recycle } from "../Icons"
import PhoneInput from "../PhoneInput"
import * as s from "./Builder.module.css"

/**
 * Question three: the words.
 *
 * Each chosen service arrives with a sentence already written — see the note
 * at the top of lib/site-draft.js for the rule about what that sentence is
 * allowed to say. Pre-filling matters because a blank textarea beside a
 * service name is where most builders lose people; editing a sentence is a
 * much smaller task than writing one.
 *
 * Business name, phone and email are deliberately empty. They cannot be
 * guessed, and inventing them would put a wrong phone number on a live site.
 */
const StepDetails = ({ draft, update, next, back }) => {
  const services = draft.services.slice(0, 3)

  const setBusiness = (key, value) => update({ business: { ...draft.business, [key]: value } })

  const setCopy = (name, value) => update({ serviceCopy: { ...draft.serviceCopy, [name]: value } })

  const resetCopy = name => setCopy(name, describeService(name, draft.tradeSlug))

  const copyFor = name =>
    draft.serviceCopy[name] !== undefined
      ? draft.serviceCopy[name]
      : describeService(name, draft.tradeSlug)

  /* ── ANOTHER WORDING — MTC-FCS-052 ──────────────────────────────────────
     Several contractors in the same trade described the same service, and
     data/services-organized.json kept all of it. Where there is more than
     one, this steps to the next: the contractor gets a choice of real
     sentences instead of one take-it-or-leave-it line.

     `spinning` is the half-second the button turns for. It is honest
     decoration — the words are already written, and nothing is being asked
     of a model — but a sentence that swaps the instant you click reads as a
     glitch, and the turn is what says "here is a different one".

     The wording is found by position rather than remembered, so a contractor
     who edits the text and comes back still moves to the next one. */
  const [spinning, setSpinning] = React.useState("")

  /* ── EVERY WORDING ON OFFER FOR ONE SERVICE — FCS-079 ─────────────────
     What real contractors wrote for this trade, and then the sentence this
     builder assembles from the service's own words. The written ones come
     first because they are better, and the assembled one is included so
     there is something to switch TO: most services have exactly one wording
     in the drop, and a button that appears only for the handful with two is
     a button nobody discovers. Both describe the same job honestly, which
     is the test for belonging in this list. */
  /* Written copy first, then the rule-based alternatives — FCS-079.
     describeOptions always returns several, so the button is offered for
     every service rather than only the ones the drop happened to cover.
     Written lines stay at the front: they were authored for this trade and
     are better than anything assembled. */
  const wordingsFor = name => {
    const written = copyVariants(draft.tradeSlug, name)
    const all = [...written]
    for (const line of describeOptions(name)) {
      if (line && !all.includes(line)) all.push(line)
    }
    return all
  }

  const cycleCopy = name => {
    const list = wordingsFor(name)
    if (list.length < 2) return

    /* A different one at RANDOM, not the next one — FCS-079. Stepping in
       order meant somebody hunting for a line they liked had to remember
       where they were in a list they cannot see; random reads as "show me
       another" and gets there in the same number of presses.

       Chosen from the OTHERS, so a press always changes something. Picking
       from the whole list would sometimes land on the line already showing
       and look like a broken button. */
    const current = copyFor(name)
    const others = list.filter(copy => copy !== current)
    const nextCopy = others.length
      ? others[Math.floor(Math.random() * others.length)]
      : list[0]

    setSpinning(name)
    window.setTimeout(() => {
      setCopy(name, nextCopy)
      setSpinning("")
    }, 480)
  }

  return (
    <div>
      <h1 className={s.question}>Tell us about your business</h1>
      <p className={s.hint}>
        We have written a starting line for each service. Change anything that does not sound like
        you — this is the text that goes on your site.
      </p>

      <div className={s.fields}>
        <div className={s.fieldRow}>
          <div className={s.field}>
            <label htmlFor="biz-name">Business name</label>
            <input
              id="biz-name"
              value={draft.business.name}
              onChange={e => setBusiness("name", e.target.value)}
              placeholder="e.g. Ridgeline Roofing"
              maxLength={60}
            />
          </div>
          <div className={s.field}>
            <label htmlFor="biz-tagline">Tagline</label>
            <input
              id="biz-tagline"
              value={draft.business.tagline}
              onChange={e => setBusiness("tagline", e.target.value)}
              placeholder="One line under your name"
              maxLength={90}
            />
          </div>
        </div>

        <div className={s.fieldRow}>
          <div className={s.field}>
            <label htmlFor="biz-phone">Phone number</label>
            <PhoneInput
              id="biz-phone"
              value={draft.business.phone}
              onChange={next => setBusiness("phone", next)}
              placeholder="(555) 123-4567"
              maxLength={24}
            />
          </div>
          <div className={s.field}>
            <label htmlFor="biz-email">Email address</label>
            <input
              id="biz-email"
              type="email"
              value={draft.business.email}
              onChange={e => setBusiness("email", e.target.value)}
              placeholder="you@yourdomain.com"
              maxLength={90}
            />
          </div>
        </div>

        {services.map((name, i) => (
          <div key={name} className={s.serviceEditor}>
            <p className={s.serviceEditorHead}>
              <span className={s.serviceEditorNum}>{i + 1}</span>
              {name}
              {wordingsFor(name).length > 1 && (
                <button
                  type="button"
                  className={s.regen}
                  data-spinning={spinning === name ? "true" : undefined}
                  onClick={() => cycleCopy(name)}
                  aria-label={`Show a different description for ${name}`}
                  title="Try another wording"
                >
                  <Recycle />
                </button>
              )}
            </p>
            <div className={s.field}>
              <label htmlFor={`svc-${i}`}>What you want customers to read</label>
              <textarea
                id={`svc-${i}`}
                value={copyFor(name)}
                onChange={e => setCopy(name, e.target.value)}
                maxLength={220}
                style={{ minHeight: 88 }}
              />
              <p className={s.fieldNote}>
                {copyFor(name).length}/220 ·{" "}
                <button type="button" className={s.linkBtn} onClick={() => resetCopy(name)}>
                  Reset to suggested
                </button>
              </p>
            </div>
          </div>
        ))}

        <div className={s.field}>
          <label htmlFor="biz-about">About your business</label>
          <textarea
            id="biz-about"
            value={draft.business.about}
            onChange={e => setBusiness("about", e.target.value)}
            placeholder="How long you have been working, what you specialise in, what customers can expect."
            maxLength={900}
          />
          <p className={s.fieldNote}>
            This is the one section worth writing yourself — it is what makes the site read like a
            real business rather than a template.
          </p>
        </div>
      </div>

      <div className={s.actions}>
        <button type="button" className={s.back} onClick={back}>
          Back
        </button>
        <button type="button" className={`btn btn--lg ${s.spacer}`} onClick={next}>
          Continue
          <ArrowRight className="btn__arrow" />
        </button>
      </div>
    </div>
  )
}

export default StepDetails
